# python
# created with help of GTP-5 mini

import json
import os
import sys
import tkinter as tk
from tkinter import ttk, messagebox, scrolledtext

class PUMLAViewerApp(tk.Tk):
    """ a simple GUI application to visualize the contents of a `modelrepo.json` file generated by pumla update."""
    def __init__(self):
        super().__init__()
        self.title("PUMLA Viewer")
        self.geometry("800x800")
        self._data = {}
        self._elements = []
        self._aliases = {}
        self._relations = []
        self._connections = []
        self._load_modelrepo()
        self._build_ui()

    def _load_modelrepo(self):
        fn = "./modelrepo.json"
        if not os.path.exists(fn):
            messagebox.showerror("File not found", f"path `{fn}` does not exist.")
            return

        text = open(fn, "r", encoding="utf-8").read()
        print(text)
        try:
            obj = json.loads(text)
            objs = [obj]
        except Exception:
            objs = []
            decoder = json.JSONDecoder()
            idx = 0
            length = len(text)
            while idx < length:
                try:
                    obj, consumed = decoder.raw_decode(text, idx)
                    objs.append(obj)
                    idx += consumed
                    while idx < length and text[idx].isspace():
                        idx += 1
                except Exception:
                    break

        elem_obj = None
        rel_obj = None
        con_obj = None
        #print(objs)
        for o in objs:
            if isinstance(o, dict) and "elements" in o:
                elem_obj = o

            if isinstance(o, dict) and "relations" in o:
                rel_obj = o

            if isinstance(o, dict) and "connections" in o:
                con_obj = o


        if not elem_obj:
            messagebox.showerror("Parsing error", "No valid `modelrepo.json` containing `elements` found.")
            return

        #self._data = model_obj
        self._elements = elem_obj.get("elements", [])
        self._relations = rel_obj.get("relations", [])
        #self._connections = con_obj.get("connections", [])
        # map alias or name -> element
        self._aliases = { (e.get("alias") or e.get("name")): e for e in self._elements }
        # map name -> relation/connection for lookup
        self._relations_map = { r.get("id"): r for r in self._relations }
        self._connections_map = { c.get("id"): c for c in self._connections }

    def _build_ui(self):

        self._logo_image = tk.PhotoImage(file= os.path.join(os.path.dirname(__file__), "../../../arch/pumla_logo.png"))
        self._logo_image = self._logo_image.subsample(4,4)
        lbl_logo = ttk.Label(self, image=self._logo_image)
        lbl_logo.pack(padx=8, pady=6, anchor="n")
        # create a bold label and use it as the LabelFrame's labelwidget so the frame title is bold
        bold_label = ttk.Label(self, text="Model Repository Information", font=("TkDefaultFont", 12, "bold"))
        info_frame = ttk.LabelFrame(self, labelwidget=bold_label)
        info_frame.pack(fill="x", padx=8, pady=6, anchor="w")

        keys_of_interest = ["modelrepopath", "modelrepofile"]
        for k in keys_of_interest:
            val = self._data.get(k, "")
            lbl = ttk.Label(info_frame, text=f"{k}: {val}")
            lbl.pack(anchor="w", padx=15, pady=2)

        tree_frame = ttk.Frame(self)
        tree_frame.pack(fill="both", expand=True, padx=8, pady=6)

        columns = ("type")
        self.tree = ttk.Treeview(tree_frame, columns=columns, show="tree headings")
        self.tree.heading("#0", text="Name")
        self.tree.heading("type", text="Type")

        vsb = ttk.Scrollbar(tree_frame, orient="vertical", command=self.tree.yview)
        hsb = ttk.Scrollbar(tree_frame, orient="horizontal", command=self.tree.xview)
        self.tree.configure(yscroll=vsb.set, xscroll=hsb.set)
        self.tree.grid(row=0, column=0, sticky="nsew")
        vsb.grid(row=0, column=1, sticky="ns")
        hsb.grid(row=1, column=0, sticky="ew")
        tree_frame.rowconfigure(0, weight=1)
        tree_frame.columnconfigure(0, weight=1)

        # Create top-level category nodes
        cat_elements = self.tree.insert("", "end", text="architectural elements", open=True)
        cat_relations = self.tree.insert("", "end", text="relations", open=True)
        cat_connections = self.tree.insert("", "end", text="connections", open=True)

        nodes = {}
        def get_parent_alias(elem):
            p = elem.get("parent", "-")
            return None if p in ("-", "", None) else p

        # Build nodes for architectural elements
        for elem in self._elements:
            alias = elem.get("alias") or elem.get("name")
            text = f"{elem.get('name', '')} ({alias})"
            values = (elem.get("type", ""))
            nodes[alias] = {"elem": elem, "text": text, "values": values, "inserted": False, "category": "elements"}

        # Insert root element nodes (those without parents) under "architectural elements"
        for alias, meta in nodes.items():
            elem = meta["elem"]
            parent_alias = get_parent_alias(elem)
            if parent_alias and parent_alias in nodes:
                continue
            try:
                self.tree.insert(cat_elements, "end", iid=alias, text=meta["text"], values=meta["values"])
            except Exception:
                iid = f"item_{len(self.tree.get_children(cat_elements))}_{alias}"
                self.tree.insert(cat_elements, "end", iid=iid, text=meta["text"], values=meta["values"])
                nodes[alias]["mapped_iid"] = iid
            else:
                nodes[alias]["mapped_iid"] = alias
            nodes[alias]["inserted"] = True

        # Insert child element nodes respecting parent relationships
        changed = True
        while changed:
            changed = False
            for alias, meta in nodes.items():
                if meta["inserted"]:
                    continue
                elem = meta["elem"]
                parent_alias = get_parent_alias(elem)
                parent_iid = None
                if parent_alias is None:
                    parent_iid = ""
                elif parent_alias in nodes and nodes[parent_alias].get("mapped_iid"):
                    parent_iid = nodes[parent_alias]["mapped_iid"]
                else:
                    continue

                try:
                    self.tree.insert(parent_iid, "end", iid=alias, text=meta["text"], values=meta["values"])
                except Exception:
                    iid = f"item_{len(self.tree.get_children(parent_iid))}_{alias}"
                    self.tree.insert(parent_iid, "end", iid=iid, text=meta["text"], values=meta["values"])
                    nodes[alias]["mapped_iid"] = iid
                else:
                    nodes[alias]["mapped_iid"] = alias
                nodes[alias]["inserted"] = True
                changed = True

            if not changed:
                for alias, meta in nodes.items():
                    if not meta["inserted"]:
                        try:
                            self.tree.insert(cat_elements, "end", iid=alias, text=meta["text"], values=meta["values"])
                        except Exception:
                            iid = f"item_{len(self.tree.get_children(cat_elements))}_{alias}"
                            self.tree.insert(cat_elements, "end", iid=iid, text=meta["text"], values=meta["values"])
                            nodes[alias]["mapped_iid"] = iid
                        else:
                            nodes[alias]["mapped_iid"] = alias
                        meta["inserted"] = True
                break

        # Add relations under "relations" category
        for relation in self._relations:
            name = relation.get("name", "(unnamed)")
            rel_type = relation.get("type", "relation")
            try:
                rel_iid = f"relation_{name}"
                self.tree.insert(cat_relations, "end", iid=rel_iid, text=name, values=(rel_type,))
            except Exception:
                rel_iid = f"relation_{len(self.tree.get_children(cat_relations))}_{name}"
                self.tree.insert(cat_relations, "end", iid=rel_iid, text=name, values=(rel_type,))

        # Add connections under "connections" category
        for connection in self._connections:
            name = connection.get("name", "(unnamed)")
            conn_type = connection.get("type", "connection")
            try:
                conn_iid = f"connection_{name}"
                self.tree.insert(cat_connections, "end", iid=conn_iid, text=name, values=(conn_type,))
            except Exception:
                conn_iid = f"connection_{len(self.tree.get_children(cat_connections))}_{name}"
                self.tree.insert(cat_connections, "end", iid=conn_iid, text=name, values=(conn_type,))

        # store mapping iid -> alias/name for lookup
        self._iid_to_alias = {}
        for alias, meta in nodes.items():
            iid = meta.get("mapped_iid") or alias
            self._iid_to_alias[iid] = alias

        # Bind selection and double click
        self.tree.bind("<<TreeviewSelect>>", self._on_select)
        self.tree.bind("<Double-1>", self._on_double_click)

        details_frame = ttk.LabelFrame(self, text="Element Details")
        details_frame.pack(fill="both", expand=False, padx=8, pady=6)
        self.details_text = scrolledtext.ScrolledText(details_frame, height=16, wrap="word")
        self.details_text.pack(fill="both", expand=True, padx=4, pady=4)

    def _format_taggedvalues(self, tagged):
        if not tagged:
            return "  (keine tagged values)"
        lines = []
        for tv in tagged:
            tag = tv.get("tag", "")
            vals = tv.get("values", [])
            vals_str = ", ".join(str(v) for v in vals) if vals else ""
            lines.append(f"  - {tag}: {vals_str}")
        return "\n".join(lines)

    def _show_element_details(self, elem):
        name = elem.get("name", "(no name)")
        alias = elem.get("alias") or name
        filename = elem.get("filename", "(no filename)")
        filepath = elem.get("path", "(no filepath)")
        type = elem.get("type", "(no type)")
        stereotypes = elem.get("stereotypes", "(no stereotypes)")

        tagged = elem.get("taggedvalues", [])

        details = []
        details.append(f"Name: {name}")
        details.append(f"Alias: {alias}")
        details.append(f"Type: {type}")
        details.append(f"Stereotypes: {stereotypes}")
        details.append(f"Filename: {filename}")
        details.append(f"File Path: {filepath}")
        details.append("Tagged Values:")
        details.append(self._format_taggedvalues(tagged))

        self.details_text.delete("1.0", "end")
        self.details_text.insert("end", "\n".join(details))

    def _get_element_by_iid_or_text(self, iid, text):
        # Try iid -> alias mapping
        alias = self._iid_to_alias.get(iid) or iid
        if alias in self._aliases:
            return self._aliases[alias]
        # fallback: try extract alias from text
        if "(" in text and text.endswith(")"):
            try:
                extracted = text[text.rfind("(")+1:-1].strip()
                if extracted in self._aliases:
                    return self._aliases[extracted]
            except Exception:
                pass
        # final fallback search by name
        name = text.split(" (")[0].strip()
        for e in self._elements:
            if e.get("name") == name or e.get("alias") == name:
                return e
        return None

    def _on_select(self, event):
        sel = self.tree.selection()
        if not sel:
            return
        iid = sel[0]
        text = (self.tree.item(iid, "text") or "").strip()
        elem = self._get_element_by_iid_or_text(iid, text)
        if elem:
            self._show_element_details(elem)
        else:
            self.details_text.delete("1.0", "end")
            self.details_text.insert("end", "Details nicht gefunden.")

    def _on_double_click(self, event):
        # Bestimme das Item unter dem Mausklick
        item_id = self.tree.identify_row(event.y)
        if not item_id:
            return
        text = (self.tree.item(item_id, "text") or "").strip()
        elem = self._get_element_by_iid_or_text(item_id, text)
        if elem:
            self._show_element_details(elem)

if __name__ == "__main__":
    args = sys.argv[1:]
    mrpath = args[0]
    os.chdir(mrpath)
    app = PUMLAViewerApp()
    app.mainloop()